# Charge daily is transaction-owned; do not erase it on unrelated partial imports.
old = """  await env.DB.prepare('DELETE FROM charge_daily_metrics WHERE store_id=? AND date BETWEEN ? AND ?').bind(storeId,month+'-01',batch.range_end).run();\n  for(const r of p.chargeDaily||[])stm.push(env.DB.prepare(`INSERT INTO charge_daily_metrics(store_id,date,charge_name,category,source_field,gross_debit,credits,net_cost,row_count,batch_id,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,CURRENT_TIMESTAMP)`).bind(storeId,r.date,r.name||'未命名费用',r.category||'其他费用',r.source||'',r.debit||0,r.credit||0,r.amount??((r.debit||0)-(r.credit||0)),r.count||0,batchId));await chunks(env.DB,stm);stm.length=0;\n"""
